class LmdbNativeKernelPartitionSafetyTest {
	private static final int FIXED_ADJACENCY = 7;
	private static final int WILDCARD_VIEW = 11;
	private static final int NODE_INTERSECTION_VIEW = 13;

	@Test
	void fixedAdjacencyAdmissionRejectsNestedRereadsButKeepsOrdinaryProbes() {
		EnumerateAdjKeys root = new EnumerateAdjKeys(FIXED_ADJACENCY, 0, 1);
		assertEquals(FIXED_ADJACENCY,
				LmdbNativeKernelPartitions.partitionableRootAdjacency(
						List.of(root, new Probe(FIXED_ADJACENCY, Operand.col(0), 2))),
				"a probe resolves a run without replacing the root key enumeration");

		for (Node nested : nestedConsumers(new EnumerateAdjKeys(FIXED_ADJACENCY, 3, 4))) {
			assertEquals(-1, LmdbNativeKernelPartitions.partitionableRootAdjacency(List.of(root, nested)),
					"nested " + nested.getClass().getSimpleName() + " rereads the complete fixed adjacency");
		}
	}

	@Test
	void wildcardAdmissionRejectsNestedBoundEnumerationsAcrossAllContainers() {
		EnumerateAdjKeys root = wildcard(WILDCARD_VIEW, Operand.constant(0), 0, 1);
		assertEquals(WILDCARD_VIEW,
				LmdbNativeKernelPartitions.partitionableRootWildcardWindow(
						List.of(root, new FilterCompareId(false, Operand.col(0), Operand.constant(1)))),
				"scalar filters do not reread the wildcard view");

		for (Node nested : nestedConsumers(wildcard(WILDCARD_VIEW, Operand.constant(1), 2, 3))) {
			assertEquals(-1, LmdbNativeKernelPartitions.partitionableRootWildcardWindow(List.of(root, nested)),
					"nested " + nested.getClass().getSimpleName() + " rereads the complete wildcard view");
		}
	}

	@Test
	void wildcardRootWindowsRequireTheWrappedViewToOwnTheRootEnumeration() {
		assertEquals(WILDCARD_VIEW, LmdbNativeKernelPartitions.partitionableRootWildcardWindow(List.of(
				new EnumerateAdjKeys(WILDCARD_VIEW, true, Operand.constant(0), 0, 1, -1, null, false, false, null))),
				"runtime-predicate adjacency enumerates the wildcard view's roots");
		assertEquals(-1, LmdbNativeKernelPartitions.partitionableRootWildcardWindow(List.of(
				new EnumerateAdjKeys(WILDCARD_VIEW, true, Operand.col(0), 0, 1, -1, null, false, false, null))),
				"a column-dependent predicate cannot be planned as a query-level wildcard root");
		assertEquals(WILDCARD_VIEW, LmdbNativeKernelPartitions.partitionableRootWildcardWindow(List.of(
				new EnumerateWildcard(WILDCARD_VIEW, true, LmdbWildcardPhysicalDemand.Demand.PAIR_PRESENCE, 0, 1, 2,
						-1, null, false))),
				"all-unbound wildcard enumeration owns both its predicate planes and roots");

		assertEquals(-1, LmdbNativeKernelPartitions.partitionableRootWildcardWindow(List.of(
				new EnumeratePredicates(WILDCARD_VIEW, true, true, LmdbWildcardPhysicalDemand.Demand.PAYLOAD,
						Operand.constant(0), null, 0, 1, -1, null, false))),
				"bound-node predicate enumeration leaves its key domain outside the wrapped view");
		assertEquals(-1, LmdbNativeKernelPartitions.partitionableRootWildcardWindow(List.of(
				new EnumerateWildcard(WILDCARD_VIEW, true, LmdbWildcardPhysicalDemand.Demand.PREDICATE_ANY, 0, 1, 2,
						-1, null, false))),
				"predicate-any short-circuit cannot be independently split by root windows");
		assertEquals(-1, LmdbNativeKernelPartitions.partitionableRootWildcardWindow(List.of(
				new SipDomainWildcard(0, WILDCARD_VIEW, true, LmdbWildcardPhysicalDemand.Demand.PAYLOAD, 0, 1, 2, -1,
						null, false))),
				"domain SIP enumerates its bound domain roots, not wildcard-view roots");
		assertEquals(-1, LmdbNativeKernelPartitions.partitionableRootWildcardWindow(List.of(
				new SipKeyWildcard(FIXED_ADJACENCY, WILDCARD_VIEW, true,
						LmdbWildcardPhysicalDemand.Demand.PAYLOAD, 0, 1, 2, -1, null, false))),
				"key SIP enumerates fixed-adjacency roots, not wildcard-view roots");
	}

	@Test
	void nodeIntersectionAdmissionRejectsNestedIntersectionRereads() {
		EnumerateNodeDomainIntersection root = new EnumerateNodeDomainIntersection(NODE_INTERSECTION_VIEW, 0);
		assertEquals(NODE_INTERSECTION_VIEW,
				LmdbNativeKernelPartitions.partitionableRootNodeDomainIntersection(
						List.of(root, new FilterCompareId(false, Operand.col(0), Operand.constant(1)))),
				"scalar filters do not reread the intersection view");

		for (Node nested : nestedConsumers(new EnumerateNodeDomainIntersection(NODE_INTERSECTION_VIEW, 2))) {
			assertEquals(-1,
					LmdbNativeKernelPartitions.partitionableRootNodeDomainIntersection(List.of(root, nested)),
					"nested " + nested.getClass().getSimpleName() + " rereads the complete intersection view");
		}
	}

	private static EnumerateAdjKeys wildcard(int view, Operand predicate, int keyColumn, int valueColumn) {
		return new EnumerateAdjKeys(view, true, predicate, keyColumn, valueColumn, -1, null, false, false, null);
	}

	private static List<Node> nestedConsumers(Node child) {
		return List.of(
				new Exists(false, List.of(child)),
				new Union(List.of(List.of(new EnumerateEntry()), List.of(child))),
				new LeftGroup(List.of(child)),
				new LexicalFrameLeftJoin(List.of(new EnumerateEntry()), List.of(child), new int[] { 0 }),
				new HashBuild(0, new int[] { 0 }, new int[] { 1 }, List.of(child), 16));
	}
}
